/**
 * Ensures every Zod schema exported from an auto-generated file has a
 * .meta() with a title string.
 *
 * Auto-generated files are identified by the comment:
 *   // THIS FILE IS AUTO-GENERATED. DO NOT EDIT.
 */
import { describe, it, expect } from "vitest";
import * as fs from "fs";
import * as path from "path";
import { fileURLToPath } from "url";
import { z } from "zod";
import * as SDK from "../index";

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const srcDir = path.resolve(__dirname, "..");

const AUTO_GEN_MARKER = "// THIS FILE IS AUTO-GENERATED. DO NOT EDIT.";

function walk(dir: string): string[] {
  const results: string[] = [];
  for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) {
      results.push(...walk(full));
    } else if (entry.isFile() && entry.name.endsWith(".ts")) {
      results.push(full);
    }
  }
  return results;
}

/** Collect all auto-generated files that export Zod schemas (not index/generatedIndex). */
function getAutoGeneratedSchemaFiles(): { file: string; exports: string[] }[] {
  const results: { file: string; exports: string[] }[] = [];

  for (const file of walk(srcDir)) {
    const norm = file.replace(/\\/g, "/");
    if (norm.includes("/tests/")) continue;
    const base = path.basename(file);
    if (base === "index.ts" || base === "generatedIndex.ts") continue;

    const content = fs.readFileSync(file, "utf-8");
    if (!content.startsWith(AUTO_GEN_MARKER)) continue;

    // Find exported const names ending in "Schema"
    const schemaExports: string[] = [];
    const re = /export const (\w+Schema)\b/g;
    let m;
    while ((m = re.exec(content)) !== null) {
      schemaExports.push(m[1]);
    }

    if (schemaExports.length > 0) {
      results.push({
        file: path.relative(path.resolve(srcDir, ".."), file).replace(/\\/g, "/"),
        exports: schemaExports,
      });
    }
  }

  return results;
}

describe("auto-generated Zod schemas have .meta({ title })", () => {
  const files = getAutoGeneratedSchemaFiles();
  const sdkExports = SDK as Record<string, unknown>;

  it("should find auto-generated schema files", () => {
    expect(files.length).toBeGreaterThan(0);
  });

  for (const { file, exports: schemaNames } of files) {
    for (const name of schemaNames) {
      it(`${name} (from ${file})`, () => {
        const schema = sdkExports[name];
        expect(schema, `${name} not found in SDK exports`).toBeDefined();
        expect(schema).toBeInstanceOf(z.ZodType);
        const meta = (schema as any).meta?.();
        expect(meta, `${name} has no .meta()`).toBeDefined();
        expect(typeof meta.title, `${name} .meta() has no title`).toBe("string");
        expect(meta.title.length, `${name} .meta().title is empty`).toBeGreaterThan(0);
      });
    }
  }
});
